    "nombres": "NOLBERTO",
    "apellidos": "ABAD JIMÉNEZ CASTILLO",
    "paciente": "NOLBERTO ABAD JIMÉNEZ CASTILLO",
    "costo": 16,
    "adelanto": 0,
    "resta": 16,
    "fec_registro": "2025-04-02",
