    "med_solicitante": "DR. JORGE ALBERTO MUÑANTE ARZAPALO",
    "nombres": "GEORGINA",
    "apellidos": "SÁNCHEZ VARGAS",
    "paciente": "GEORGINA SÁNCHEZ VARGAS",
    "costo": 8,
    "adelanto": 0,
    "resta": 8,
    "fec_registro": "2025-03-13",
